def Q(qid, prompts, options, correct, explanations, wrong_explanations, categories, followups):
    """Build one fully localized question with an explanation for each distractor."""
    return {
        "id": qid,
        "prompt": dict(zip(LOCALES, prompts)),
        "options": {loc: [item[i] for item in options] for i, loc in enumerate(LOCALES)},
        "correct": correct,
        "correct_why": dict(zip(LOCALES, explanations)),
        "wrong_why": {loc: [item[i] for item in wrong_explanations] for i, loc in enumerate(LOCALES)},
        "category": dict(zip(LOCALES, categories)),
        "followup": dict(zip(LOCALES, followups)),
    }


def QX(qid, prompts, options, correct, explanations, wrongs, categories, followups):
    """Build a localized question from one rationale per incorrect choice."""
    wrong_by_index = iter(wrongs)
    wrong_full = [("", "", "") if i == correct else next(wrong_by_index) for i in range(len(options))]
    return Q(qid, prompts, options, correct, explanations, wrong_full, categories, followups)


def MODE(title, intro, objectives, sections, examples, demo):
    return {"title": title, "intro": intro, "objectives": objectives,
            "sections": sections, "worked_examples": examples, "demo_instructions": demo}


def L(slug, group, difficulty, minutes, summary, prerequisites, modes, demo_kind, truth_tables, source_keys, quiz):
    return {"slug": slug, "group": group, "difficulty": difficulty, "minutes": minutes,
            "summary": summary, "prerequisites": prerequisites, "modes": modes,
            "demo_kind": demo_kind, "truth_tables": truth_tables,
            "sources": [SOURCES[k] for k in source_keys], "quiz": quiz}


