for _lesson in LESSONS:
    _lesson["quiz"].extend(_EXTRAS.get(_lesson["slug"], []))

BY_SLUG = {item["slug"]: item for item in LESSONS}
assert len(BY_SLUG) == 9 and len(LESSONS) == 9


def question_bank(slug: str, locale: str = "en"):
    if locale not in LOCALES:
        locale = "en"
    lesson = BY_SLUG.get(slug)
    if lesson is None:
        return None
    out = []
    for q in lesson["quiz"]:
        misses = {str(i): {"category": q["category"][locale], "why": q["wrong_why"][locale][i]}
                  for i in range(len(q["options"][locale])) if i != q["correct"]}
        out.append({"id":q["id"], "prompt":q["prompt"][locale], "options":q["options"][locale],
                    "correct":q["correct"], "correct_why":q["correct_why"][locale],
                    "misconceptions":misses, "followup":q["followup"][locale]})
    return out


def public_question_list(slug: str, locale: str = "en"):
    bank = question_bank(slug, locale)
    if bank is None:
        return None
    return [{"id":q["id"], "prompt":q["prompt"], "options":q["options"]} for q in bank]


def public_lesson(slug: str):
    item = BY_SLUG.get(slug)
    if item is None:
        return None
    return {
        "slug":item["slug"], "group":item["group"], "difficulty":item["difficulty"],
        "minutes":item["minutes"], "summary":deepcopy(item["summary"]),
        "prerequisites":item["prerequisites"], "modes":deepcopy(item["modes"]),
        "demo_kind":item["demo_kind"], "truth_tables":deepcopy(item["truth_tables"]),
        "sources":deepcopy(item["sources"]), "quiz_count":len(item["quiz"]),
    }
